import { AppError } from '../../../../shared/errors/AppError.js';

const PATTERN = /^KCF-\d{5,}$/;
const MAX_LENGTH = 32;

/** Immutable identifier generated by the back end, e.g. "KCF-00002" (BR 2, D1). */
export class KitchenConfigurationId {
  #value;
  constructor(value) {
    const normalized =
      typeof value === 'string' ? value.trim().toUpperCase() : '';
    if (normalized.length > MAX_LENGTH || !PATTERN.test(normalized))
      throw new AppError('Invalid kitchen configuration id');
    this.#value = normalized;
    Object.freeze(this);
  }
  static create(value) {
    return value instanceof KitchenConfigurationId
      ? value
      : new KitchenConfigurationId(value);
  }
  getValue() {
    return this.#value;
  }
  equals(other) {
    return (
      other instanceof KitchenConfigurationId &&
      other.getValue() === this.#value
    );
  }
  toString() {
    return this.#value;
  }
}